import { spanishWic } from "./wic-locale";
import { SNAP_SPANISH_COPY } from "./snap-copy";
export type ParentLocale = "en" | "es";
export const PARENT_LOCALE_COOKIE = "caselink-parent-ui-locale";
export function parentLocale(value: unknown): ParentLocale {
  return value === "es" ? "es" : "en";
}
export function explicitParentLocale(value: unknown): ParentLocale | undefined {
  return value === "en" || value === "es" ? value : undefined;
}
export function parentRecoveryHref(href: string, locale: ParentLocale): string {
  const url = new URL(href, "https://caselink.invalid");
  url.searchParams.set("ui", parentLocale(locale));
  return href.startsWith("/") ? `${url.pathname}${url.search}${url.hash}` : url.href;
}

/** Interface copy only. Program contact language and original evidence keep their own meaning. */
export function parentText(locale: ParentLocale, english: string): string {
  return locale === "es" && Object.hasOwn(spanish, english) ? spanish[english as keyof typeof spanish] : english;
}

